#!/usr/bin/env node

/**
 * Environment Configuration Validator
 * Validates that all required environment variables are set
 * and that hardcoded values have been externalized
 */

require('dotenv').config();

const config = {
  // Required variables for production
  requiredProduction: [
    'NODE_ENV',
    'PORT',
    'HOST'
  ],

  // Required variables for all environments
  requiredAll: [
    'NODE_ENV'
  ],

  // Recommended variables (warnings if missing)
  recommended: [
    'ALLOWED_ORIGINS',
    'PRIMARY_DOMAIN',
    'API_TOKEN',
    'LOG_LEVEL'
  ],

  // Variables that replace hardcoded values
  replacements: {
    'PORT': 'Replaces hardcoded port 3000',
    'HOST': 'Replaces hardcoded host 0.0.0.0',
    'ALLOWED_ORIGINS': 'Replaces hardcoded CORS origins',
    'PRIMARY_DOMAIN': 'Replaces hardcoded domain in CORS',
    'MOCK_USER_1_EMAIL': 'Replaces hardcoded alice@example.com',
    'MOCK_USER_2_EMAIL': 'Replaces hardcoded bob@example.com'
  },

  // Validation patterns
  patterns: {
    PORT: /^\d+$/,
    NODE_ENV: /^(development|staging|production|test)$/,
    EMAIL: /^[^@\s]+@[^@\s]+\.[^@\s]+$/,
    URL: /^https?:\/\/.+/,
    BOOLEAN: /^(true|false)$/
  },

  // Default values for development
  defaults: {
    PORT: '3000',
    HOST: '0.0.0.0',
    NODE_ENV: 'development',
    LOG_LEVEL: 'info'
  }
};

function validateEnvironment() {
  const env = process.env.NODE_ENV || 'development';
  const errors = [];
  const warnings = [];
  const successes = [];

  console.log(`🔍 Validating environment configuration (${env})`);
  console.log('=' .repeat(60));

  // Check required variables for all environments
  config.requiredAll.forEach(varName => {
    if (!process.env[varName]) {
      errors.push(`❌ Missing required variable: ${varName}`);
    } else {
      successes.push(`✅ Required variable set: ${varName}=${maskSensitive(varName, process.env[varName])}`);
    }
  });

  // Check required variables for production
  if (env === 'production') {
    config.requiredProduction.forEach(varName => {
      if (!process.env[varName]) {
        errors.push(`❌ Missing required production variable: ${varName}`);
      } else {
        successes.push(`✅ Production variable set: ${varName}=${maskSensitive(varName, process.env[varName])}`);
      }
    });
  }

  // Check recommended variables
  config.recommended.forEach(varName => {
    if (!process.env[varName]) {
      warnings.push(`⚠️  Recommended variable not set: ${varName}`);
    } else {
      successes.push(`✅ Recommended variable set: ${varName}=${maskSensitive(varName, process.env[varName])}`);
    }
  });

  // Validate variable patterns
  Object.keys(process.env).forEach(varName => {
    const value = process.env[varName];

    // Check for patterns
    if (varName === 'PORT' && config.patterns.PORT && !config.patterns.PORT.test(value)) {
      errors.push(`❌ Invalid PORT format: ${value} (must be a number)`);
    }

    if (varName === 'NODE_ENV' && config.patterns.NODE_ENV && !config.patterns.NODE_ENV.test(value)) {
      errors.push(`❌ Invalid NODE_ENV: ${value} (must be development, staging, production, or test)`);
    }

    // Check email patterns for mock user emails
    if (varName.includes('EMAIL') && config.patterns.EMAIL && !config.patterns.EMAIL.test(value)) {
      warnings.push(`⚠️  Invalid email format for ${varName}: ${value}`);
    }
  });

  // Check for hardcoded value replacements
  Object.keys(config.replacements).forEach(varName => {
    const explanation = config.replacements[varName];
    if (!process.env[varName] && env === 'production') {
      warnings.push(`⚠️  Hardcoded value not externalized: ${varName} - ${explanation}`);
    } else if (process.env[varName]) {
      successes.push(`✅ Hardcoded value externalized: ${varName} - ${explanation}`);
    }
  });

  // Check for default values being used in production
  if (env === 'production') {
    Object.keys(config.defaults).forEach(varName => {
      if (process.env[varName] === config.defaults[varName]) {
        warnings.push(`⚠️  Using default value in production for ${varName}: ${config.defaults[varName]}`);
      }
    });
  }

  // Display results
  if (successes.length > 0) {
    console.log('\n✅ SUCCESSES:');
    successes.forEach(msg => console.log(`  ${msg}`));
  }

  if (warnings.length > 0) {
    console.log('\n⚠️  WARNINGS:');
    warnings.forEach(msg => console.log(`  ${msg}`));
  }

  if (errors.length > 0) {
    console.log('\n❌ ERRORS:');
    errors.forEach(msg => console.log(`  ${msg}`));
    console.log('\n❌ Configuration validation failed!');
    process.exit(1);
  }

  // Summary
  console.log('\n' + '='.repeat(60));
  console.log('📊 SUMMARY:');
  console.log(`  Environment: ${env}`);
  console.log(`  Total variables set: ${Object.keys(process.env).filter(k => k.startsWith('npm_') === false).length}`);
  console.log(`  Successes: ${successes.length}`);
  console.log(`  Warnings: ${warnings.length}`);
  console.log(`  Errors: ${errors.length}`);

  if (errors.length === 0 && warnings.length === 0) {
    console.log('\n🎉 All checks passed! Configuration looks good.');
  } else if (errors.length === 0) {
    console.log('\n👍 Configuration passes, but review warnings above.');
  }

  // Check for remaining hardcoded values in source files
  console.log('\n' + '='.repeat(60));
  console.log('🔎 Checking source files for remaining hardcoded values...');

  const hardcodedChecks = [
    { pattern: '3000', description: 'Hardcoded port' },
    { pattern: 'localhost:3000', description: 'Hardcoded localhost URL' },
    { pattern: 'localhost:3001', description: 'Hardcoded localhost URL' },
    { pattern: 'example.com', description: 'Hardcoded example domain' },
    { pattern: 'alice@example.com', description: 'Hardcoded email' },
    { pattern: 'bob@example.com', description: 'Hardcoded email' },
    { pattern: '0.0.0.0', description: 'Hardcoded host' },
