// Secure Express Application with Security Best Practices
// Enhanced version of app.js with security fixes

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ======================
// SECURITY CONFIGURATION
// ======================

// 1. Security Headers with Helmet
// Sets various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  // Disable X-Powered-By header
  hidePoweredBy: true,
  // Prevent clickjacking
  frameguard: { action: 'deny' },
  // Prevent MIME-sniffing
  noSniff: true,
  // XSS protection
  xssFilter: true,
}));

// 2. Rate Limiting
// Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. Body Parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// 4. Basic CORS Configuration
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.header('Access-Control-Allow-Credentials', 'false');
  next();
});

// ======================
// AUTHENTICATION MIDDLEWARE
// ======================

// Simple API key authentication (for demonstration)
// In production, use JWT/OAuth2/Passport.js
const apiKeyAuth = (req, res, next) => {
  const apiKey = req.headers['x-api-key'] || req.query.apiKey;
  const validApiKey = process.env.API_KEY;

  if (!validApiKey) {
    console.warn('API_KEY not set in environment');
    return next();
  }

  if (!apiKey || apiKey !== validApiKey) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Valid API key required'
    });
  }

  next();
};

// ======================
// ROUTES WITH SECURITY
// ======================

// Public health endpoint (no authentication required)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Protected users endpoint with authentication
app.get('/users', apiKeyAuth, (req, res) => {
  // In production, this would come from a database
  // with proper access controls
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply data minimization - only return necessary fields
  // based on user permissions
  const safeUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    // Email might be omitted or masked based on requirements
    email: process.env.NODE_ENV === 'production' ? '****' : user.email
  }));

  res.json(safeUsers);
});

// Example POST endpoint with input validation
app.post('/users',
  apiKeyAuth,
  [
    // Input validation
    body('name').trim().notEmpty().withMessage('Name is required'),
    body('email').isEmail().withMessage('Valid email required'),
    body('age').optional().isInt({ min: 0, max: 150 })
  ],
  (req, res) => {
    // Check validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Process valid data
    const { name, email, age } = req.body;

    // In production: sanitize and store in database
    res.status(201).json({
      message: 'User created successfully',
      data: { name, email, age: age || null }
    });
  }
);

// ======================
// ERROR HANDLING
// ======================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', {
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Don't leak internal error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: message
  });
});

// ======================
// SERVER CONFIGURATION
// ======================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0'; // Bind to all interfaces

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode`);
  console.log(`Listening on http://${HOST}:${PORT}`);
  console.log(`Security middleware: Helmet, Rate limiting, CORS enabled`);
});

// Graceful shutdown for production
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

