// Fully Configurable Secure Express Application
// All hardcoded values replaced with environment variables

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ======================
// CONFIGURATION
// ======================

const config = {
  // Server Configuration
  server: {
    port: parseInt(process.env.PORT) || 3000,
    host: process.env.HOST || '127.0.0.1',
    nodeEnv: process.env.NODE_ENV || 'development',
    shutdownTimeout: parseInt(process.env.SHUTDOWN_TIMEOUT) || 30, // seconds
  },

  // Security Headers Configuration
  security: {
    corsEnabled: process.env.ENABLE_CORS !== 'false',
    allowedOrigins: process.env.ALLOWED_ORIGINS ? 
      process.env.ALLOWED_ORIGINS.split(',') : [],
    enableSecurityHeaders: process.env.ENABLE_SECURITY_HEADERS !== 'false',
  },

  // Rate Limiting Configuration
  rateLimit: {
    enabled: process.env.ENABLE_RATE_LIMITING !== 'false',
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
    maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  },

  // Payload Configuration
  payload: {
    jsonLimit: process.env.JSON_PAYLOAD_LIMIT || '10kb',
    urlencodedLimit: process.env.FORM_PAYLOAD_LIMIT || '10kb',
  },

  // Authentication Configuration
  auth: {
    apiKey: process.env.API_KEY,
    strictMode: process.env.STRICT_AUTH_MODE === 'true',
    authEnabled: process.env.ENABLE_AUTHENTICATION !== 'false',
  },

  // Logging Configuration
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    includeStackTraces: process.env.LOG_ERROR_STACK_TRACE === 'true',
    logAuthFailures: process.env.LOG_AUTH_FAILURES === 'true',
  },

  // Feature Flags
  features: {
    healthEndpoint: process.env.ENABLE_HEALTH_ENDPOINT !== 'false',
    usersEndpoint: process.env.ENABLE_USERS_ENDPOINT !== 'false',
  },
};

// ======================
// CONFIGURATION VALIDATION
// ======================

function validateConfiguration() {
  console.log('Validating configuration...');

  // Required variables
  const requiredVars = [];
  const missingRequired = requiredVars.filter(varName => !process.env[varName]);

  if (missingRequired.length > 0) {
    throw new Error(`Missing required environment variables: ${missingRequired.join(', ')}`);
  }

  // Security warnings for production
  if (config.server.nodeEnv === 'production') {
    const recommendedVars = ['API_KEY', 'ALLOWED_ORIGINS'];
    const missingRecommended = recommendedVars.filter(varName => !process.env[varName]);

    if (missingRecommended.length > 0) {
      console.warn(`⚠️  SECURITY WARNING: Missing recommended environment variables: ${missingRecommended.join(', ')}`);
    }

    if (!config.auth.apiKey && config.auth.authEnabled) {
      console.warn('⚠️  SECURITY WARNING: Authentication is enabled but API_KEY is not set!');
    }

    if (config.security.allowedOrigins.length === 0 && config.security.corsEnabled) {
      console.warn('⚠️  SECURITY WARNING: CORS is enabled but no origins are specified!');
    }
  }

  console.log('Configuration validated successfully');
  console.log(`Environment: ${config.server.nodeEnv}`);
  console.log(`Server will bind to: ${config.server.host}:${config.server.port}`);
}

// ======================
// SECURITY MIDDLEWARE
// ======================

// Security headers with Helmet
if (config.security.enableSecurityHeaders) {
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        styleSrc: ["'self'"],
        imgSrc: ["'self'", "data:"],
      },
    },
    hidePoweredBy: true,
    frameguard: { action: 'deny' },
    noSniff: true,
    xssFilter: true,
  }));
} else {
  console.warn('⚠️  Security headers are disabled. Not recommended for production!');
}

// Rate limiting
if (config.rateLimit.enabled) {
  const limiter = rateLimit({
    windowMs: config.rateLimit.windowMs,
    max: config.rateLimit.maxRequests,
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(limiter);
  console.log(`Rate limiting enabled: ${config.rateLimit.maxRequests} requests per ${config.rateLimit.windowMs / 60000} minutes`);
}

// CORS configuration
if (config.security.corsEnabled && config.security.allowedOrigins.length > 0) {
  app.use((req, res, next) => {
    const origin = req.headers.origin;
    if (config.security.allowedOrigins.includes(origin)) {
      res.header('Access-Control-Allow-Origin', origin);
      res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
      res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
      res.header('Access-Control-Allow-Credentials', 'false');
    }
    next();
  });
  console.log(`CORS enabled for origins: ${config.security.allowedOrigins.join(', ')}`);
} else if (config.security.corsEnabled) {
  console.warn('⚠️  CORS enabled but no allowed origins specified. This may be insecure!');
}

// Body parsing with configurable limits
app.use(express.json({ limit: config.payload.jsonLimit }));
app.use(express.urlencoded({ extended: false, limit: config.payload.urlencodedLimit }));

// ======================
// AUTHENTICATION MIDDLEWARE
// ======================

const apiKeyAuth = (req, res, next) => {
  if (!config.auth.authEnabled) {
    return next(); // Authentication disabled
  }

  if (!config.auth.apiKey) {
    if (config.auth.strictMode) {
      return res.status(500).json({ 
        error: 'Server configuration error' 
      });
    }

    // Log warning but allow in non-strict mode
    if (config.logging.logAuthFailures) {
      console.warn('Authentication attempted but API_KEY not configured');
    }
    return next();
  }

  const apiKey = req.headers['x-api-key'] || req.query.apiKey;

  if (!apiKey) {
    if (config.logging.logAuthFailures) {
      console.warn('Authentication failed: No API key provided');
    }
    return res.status(401).json({
      error: 'Authentication required'
    });
  }

  if (apiKey !== config.auth.apiKey) {
    if (config.logging.logAuthFailures) {
      console.warn('Authentication failed: Invalid API key');
    }
    return res.status(401).json({
      error: 'Authentication failed'
    });
  }

  next();
};

// ======================
// ROUTES
// ======================

// Health endpoint (configurable)
if (config.features.healthEndpoint) {
  app.get('/health', (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: config.server.nodeEnv,
      version: process.env.APP_VERSION || '1.0.0',
      uptime: process.uptime(),
    });
  });
}

// Users endpoint (configurable with authentication)
if (config.features.usersEndpoint) {
  app.get('/users', apiKeyAuth, (req, res) => {
    // Mock data - in production, this should come from a database
    // with proper environment-specific configuration
    const mockUsers = process.env.MOCK_USERS_DATA ? 
      JSON.parse(process.env.MOCK_USERS_DATA) : [
        { id: 1, name: 'Test User 1', email: 'test1@example.com' },
        { id: 2, name: 'Test User 2', email: 'test2@example.com' },
      ];

    // Apply data minimization based on configuration
    const showEmails = process.env.SHOW_USER_EMAILS === 'true' || 
                      config.server.nodeEnv !== 'production';

    const safeUsers = mockUsers.map(user => ({
      id: user.id,
      name: user.name,
      email: showEmails ? user.email : '****',
    }));

    res.json(safeUsers);
  });
}

// Example POST endpoint with validation
app.post('/users',
  apiKeyAuth,
  [
    body('name').trim().notEmpty().withMessage('Name is required'),
    body('email').isEmail().withMessage('Valid email required'),
    body('age').optional().isInt({ 
      min: parseInt(process.env.MIN_USER_AGE) || 0, 
      max: parseInt(process.env.MAX_USER_AGE) || 150 
    })
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { name, email, age } = req.body;

    // In production: sanitize and store in database
    res.status(201).json({
      message: 'User created successfully',
      data: { name, email, age: age || null },
      timestamp: new Date().toISOString(),
    });
  }
);

// ======================
// ERROR HANDLING
// ======================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString(),
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  const errorDetails = {
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    error: err.message,
  };

  if (config.logging.includeStackTraces) {
    errorDetails.stack = err.stack;
  }

  console.error('Error:', errorDetails);

  const message = config.server.nodeEnv === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: message,
    timestamp: new Date().toISOString(),
  });
});

// ======================
// SERVER STARTUP
// ======================

// Validate configuration before starting
try {
  validateConfiguration();
} catch (error) {
  console.error('Configuration validation failed:', error.message);
  process.exit(1);
}

const server = app.listen(config.server.port, config.server.host, () => {
  console.log('='.repeat(60));
  console.log(`Server Configuration:`);
  console.log(`- Environment: ${config.server.nodeEnv}`);
  console.log(`- Host: ${config.server.host}`);
  console.log(`- Port: ${config.server.port}`);
  console.log(`- Security Headers: ${config.security.enableSecurityHeaders ? 'Enabled' : 'Disabled'}`);
  console.log(`- Rate Limiting: ${config.rateLimit.enabled ? 'Enabled' : 'Disabled'}`);
  console.log(`- Authentication: ${config.auth.authEnabled ? 'Enabled' : 'Disabled'}`);
  console.log('='.repeat(60));
  console.log(`Server started successfully at http://${config.server.host}:${config.server.port}`);
});

// ======================
// GRACEFUL SHUTDOWN
// ======================

function gracefulShutdown(signal) {
  console.log(`\n${signal} received: starting graceful shutdown...`);

  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, config.server.shutdownTimeout * 1000);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to exit here
  if (config.server.nodeEnv === 'production') {
    gracefulShutdown('UNHANDLED_REJECTION');
  }
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to exit here
  if (config.server.nodeEnv === 'production') {
    gracefulShutdown('UNCAUGHT_EXCEPTION');
  }
});

module.exports = {
  app,
  config,
  server,
};

#!/usr/bin/env node

/**
 * Configuration Validation Script
 * Run this before starting the server to validate environment configuration
 */

require('dotenv').config();

const fs = require('fs');
const path = require('path');

class ConfigValidator {
  constructor() {
    this.errors = [];
    this.warnings = [];
    this.config = {};
  }

  /**
   * Validate all configuration
   */
  validate() {
    this.validateRequired();
    this.validateSecurity();
    this.validateTypes();
    this.validateRanges();

    return {
      isValid: this.errors.length === 0,
      errors: this.errors,
      warnings: this.warnings,
      config: this.config
    };
  }

  /**
   * Validate required environment variables
   */
  validateRequired() {
    const required = [
      'NODE_ENV'
    ];

    for (const varName of required) {
      if (!process.env[varName]) {
        this.errors.push(`Required environment variable ${varName} is not set`);
      }
    }
  }

  /**
   * Validate security-related configuration
   */
  validateSecurity() {
    const nodeEnv = process.env.NODE_ENV || 'development';

    // Security warnings for production
    if (nodeEnv === 'production') {
      const securityVars = ['API_KEY'];
      for (const varName of securityVars) {
        if (!process.env[varName]) {
          this.warnings.push(`Security: ${varName} is recommended in production but not set`);
        }
      }

      // Check for weak/default values
      if (process.env.API_KEY && process.env.API_KEY.includes('example') || 
          process.env.API_KEY && process.env.API_KEY.length < 20) {
        this.warnings.push('Security: API key may be weak or default value');
      }

      // Check CORS configuration
      if (process.env.ENABLE_CORS !== 'false' && !process.env.ALLOWED_ORIGINS) {
        this.warnings.push('Security: CORS enabled but no allowed origins specified');
      }
    }

    // Development warnings
    if (nodeEnv === 'development') {
      if (process.env.ENABLE_SECURITY_HEADERS === 'false') {
        this.warnings.push('Development: Security headers disabled - not recommended');
      }

      if (process.env.ENABLE_RATE_LIMITING === 'false') {
        this.warnings.push('Development: Rate limiting disabled - test with it enabled');
      }
    }
  }

  /**
   * Validate data types
   */
  validateTypes() {
    const validators = {
      PORT: this.validatePort,
      RATE_LIMIT_WINDOW_MS: this.validatePositiveInt,
      RATE_LIMIT_MAX_REQUESTS: this.validatePositiveInt,
      SHUTDOWN_TIMEOUT: this.validatePositiveInt,
      MIN_USER_AGE: this.validateNonNegativeInt,
      MAX_USER_AGE: this.validatePositiveInt,
    };

    for (const [varName, validator] of Object.entries(validators)) {
      if (process.env[varName]) {
        const result = validator.call(this, varName, process.env[varName]);
        if (result !== true) {
          this.errors.push(result);
        }
      }
    }
  }

  /**
   * Validate numeric ranges
   */
  validateRanges() {
    // Port validation
    if (process.env.PORT) {
      const port = parseInt(process.env.PORT);
      if (port < 1 || port > 65535) {
        this.errors.push(`PORT must be between 1 and 65535, got ${port}`);
      }
    }

    // Age validation
    if (process.env.MIN_USER_AGE && process.env.MAX_USER_AGE) {
      const minAge = parseInt(process.env.MIN_USER_AGE);
      const maxAge = parseInt(process.env.MAX_USER_AGE);

      if (minAge > maxAge) {
        this.errors.push(`MIN_USER_AGE (${minAge}) cannot be greater than MAX_USER_AGE (${maxAge})`);
      }
    }

    // Rate limiting validation
    if (process.env.RATE_LIMIT_WINDOW_MS) {
      const windowMs = parseInt(process.env.RATE_LIMIT_WINDOW_MS);
      if (windowMs < 1000) {
        this.warnings.push(`Rate limiting window is very short: ${windowMs}ms`);
      }
    }
  }

  /**
   * Helper validation methods
   */
  validatePort(varName, value) {
    const port = parseInt(value);
    if (isNaN(port)) {
      return `${varName} must be a number, got: ${value}`;
    }
    if (port < 1 || port > 65535) {
      return `${varName} must be between 1 and 65535, got: ${port}`;
    }
    return true;
  }

  validatePositiveInt(varName, value) {
    const num = parseInt(value);
    if (isNaN(num)) {
      return `${varName} must be a number, got: ${value}`;
    }
    if (num <= 0) {
      return `${varName} must be positive, got: ${num}`;
    }
    return true;
  }

  validateNonNegativeInt(varName, value) {
    const num = parseInt(value);
    if (isNaN(num)) {
      return `${varName} must be a number, got: ${value}`;
    }
    if (num < 0) {
      return `${varName} must be non-negative, got: ${num}`;
    }
    return true;
  }

  /**
   * Generate configuration report
   */
  generateReport() {
    const result = this.validate();

    console.log('='.repeat(60));
    console.log('CONFIGURATION VALIDATION REPORT');
    console.log('='.repeat(60));

    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log(`Validation: ${result.isValid ? '✅ PASSED' : '❌ FAILED'}`);
    console.log('');

    // Show errors
    if (result.errors.length > 0) {
      console.log('❌ ERRORS:');
      result.errors.forEach(error => {
        console.log(`  - ${error}`);
      });
      console.log('');
    }

    // Show warnings
    if (result.warnings.length > 0) {
      console.log('⚠️  WARNINGS:');
      result.warnings.forEach(warning => {
        console.log(`  - ${warning}`);
      });
      console.log('');
    }

    // Show important configuration values (masked)
    console.log('📋 CONFIGURATION SUMMARY:');
    const importantVars = [
      'NODE_ENV', 'PORT', 'HOST',
      'ENABLE_SECURITY_HEADERS', 'ENABLE_RATE_LIMITING', 'ENABLE_AUTHENTICATION',
      'ENABLE_CORS', 'LOG_LEVEL'
    ];

    importantVars.forEach(varName => {
      let value = process.env[varName];
      if (value === undefined) value = '(not set)';

      // Mask sensitive values
      if (varName.includes('KEY') || varName.includes('SECRET') || varName.includes('PASSWORD')) {
        value = '********';
      }

      console.log(`  ${varName}=${value}`);
    });

    console.log('');
    console.log('='.repeat(60));

    return result;
  }
}

/**
 * Main execution
 */
function main() {
  const validator = new ConfigValidator();
  const result = validator.generateReport();

  // Check if we should exit with error code
  if (!result.isValid) {
    console.error('\n❌ Configuration validation failed. Please fix errors before starting.');
    process.exit(1);
  }

  if (result.warnings.length > 0) {
    console.log('\n⚠️  Configuration has warnings. Review before deploying to production.');
  } else {
    console.log('\n✅ Configuration validation successful!');
  }
}

// Run if called directly
if (require.main === module) {
  main();
}

module.exports = ConfigValidator;

