// Security test for app.js
const fs = require('fs');
const path = require('path');

console.log('=== Security Analysis of app.js ===\n');

// Read the app.js file
const appContent = fs.readFileSync('app.js', 'utf8');

// Check for common vulnerabilities
const checks = [
  {
    name: 'Hardcoded Secrets',
    pattern: /(password|secret|key|token|credential)[\s]*[:=][\s]*['"][^'"]+['"]/gi,
    severity: 'HIGH'
  },
  {
    name: 'Console Log Statements',
    pattern: /console\.(log|debug|info|warn|error)\(/g,
    severity: 'MEDIUM',
    note: 'Could leak sensitive information in production'
  },
  {
    name: 'No Input Validation',
    pattern: /req\.(params|query|body)/g,
    severity: 'MEDIUM',
    note: 'Found parameters usage but no validation middleware'
  },
  {
    name: 'Missing Error Handling',
    pattern: /catch\s*\(/g,
    severity: 'MEDIUM',
    note: 'No try-catch blocks found'
  },
  {
    name: 'Eval or Dangerous Functions',
    pattern: /(eval|Function|setTimeout|setInterval)\(.*['"][^)]+['"]/g,
    severity: 'CRITICAL'
  }
];

let issuesFound = [];

checks.forEach(check => {
  const matches = appContent.match(check.pattern);
  if (matches) {
    issuesFound.push({
      check: check.name,
      severity: check.severity,
      matches: matches.length,
      note: check.note || ''
    });
  }
});

// Check for security middleware
const securityMiddleware = [
  'helmet',
  'cors',
  'express-validator',
  'express-rate-limit',
  'csrf',
  'bcrypt',
  'jsonwebtoken',
  'passport'
];

securityMiddleware.forEach(middleware => {
  if (!appContent.includes(middleware)) {
    issuesFound.push({
      check: `Missing ${middleware}`,
      severity: middleware === 'helmet' ? 'HIGH' : 'MEDIUM',
      matches: 0,
      note: `Security middleware not found: ${middleware}`
    });
  }
});

// Check for environment variable usage
const envUsage = appContent.match(/process\.env\.[A-Z_]+/g);
if (!envUsage || envUsage.length === 0) {
  issuesFound.push({
    check: 'No Environment Variables',
    severity: 'MEDIUM',
    matches: 0,
    note: 'Application not using environment variables for configuration'
  });
}

// Display results
console.log('Issues Found:');
issuesFound.forEach(issue => {
  console.log(`\n[${issue.severity}] ${issue.check}`);
  if (issue.matches > 0) {
    console.log(`  Found ${issue.matches} occurrence(s)`);
  }
  if (issue.note) {
    console.log(`  Note: ${issue.note}`);
  }
});

console.log('\n=== Environment File Analysis ===');
const envPath = '.env.test';
if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  const sensitivePatterns = [
    { name: 'API Keys', pattern: /_KEY\s*=/g },
    { name: 'Secrets', pattern: /_SECRET\s*=/g },
    { name: 'Passwords', pattern: /PASSWORD\s*=|_PWD\s*=/gi },
    { name: 'Database URLs', pattern: /DATABASE_URL\s*=/g },
    { name: 'Tokens', pattern: /_TOKEN\s*=/g }
  ];

  console.log(`\nChecking ${envPath}:`);
  sensitivePatterns.forEach(pattern => {
    const matches = envContent.match(pattern.pattern);
    if (matches) {
      console.log(`  [CRITICAL] Found ${matches.length} ${pattern.name} in environment file`);
    }
  });

  // Count total lines with potential secrets
  const lines = envContent.split('\n');
  const secretLines = lines.filter(line => 
    line.includes('=') && 
    !line.trim().startsWith('#') &&
    line.includes('=')
  );
  console.log(`  Total configuration lines: ${secretLines.length}`);
}

console.log('\n=== Recommendations ===');
console.log('1. Add helmet.js for security headers');
console.log('2. Implement input validation with express-validator');
console.log('3. Add rate limiting');
console.log('4. Use environment variables for configuration');
console.log('5. Remove or secure .env.test file');
console.log('6. Add authentication for sensitive endpoints');
console.log('7. Implement proper error handling');
console.log('8. Add CORS configuration');
console.log('9. Consider using HTTPS/TLS');
console.log('10. Add logging and monitoring');

// Secured version of app.js with common security fixes

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const winston = require('winston');
const basicAuth = require('express-basic-auth');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Configure CORS - be specific about allowed origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? 
    process.env.ALLOWED_ORIGINS.split(',') : 
    'http://localhost:3001',
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// Parse JSON with size limit
app.use(express.json({ limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.url}`, {
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });
  next();
});

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method
  });

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    res.status(500).json({ error: 'Internal server error' });
  } else {
    res.status(500).json({ 
      error: err.message,
      stack: err.stack 
    });
  }
});

// Health endpoint (minimal information disclosure)
app.get('/health', [
  query('detailed').optional().isBoolean()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const detailed = req.query.detailed === 'true';
  const response = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  };

  // Only include detailed info if explicitly requested
  if (detailed && process.env.NODE_ENV !== 'production') {
    response.version = process.env.APP_VERSION;
    response.nodeVersion = process.version;
  }

  res.json(response);
});

// Basic authentication for sensitive endpoints
const usersAuth = basicAuth({
  users: { 
    [process.env.ADMIN_USER || 'admin']: process.env.ADMIN_PASSWORD || 'change_this_password' 
  },
  challenge: true,
  unauthorizedResponse: { error: 'Unauthorized' }
});

// Users endpoint with authentication and validation
app.get('/users', usersAuth, [
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // In a real application, this would come from a database
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      role: 'user'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      role: 'user'
    }
  ];

  // Apply pagination
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;
  const paginatedUsers = users.slice(offset, offset + limit);

  // Sanitize response - remove sensitive fields if needed
  const sanitizedUsers = paginatedUsers.map(user => ({
    id: user.id,
    name: user.name,
    role: user.role
    // Note: email removed from response for privacy
  }));

  res.json({
    users: sanitizedUsers,
    pagination: {
      total: users.length,
      limit,
      offset,
      hasMore: offset + limit < users.length
    }
  });
});

// Create user endpoint with validation
app.post('/users', [
  body('name').trim().notEmpty().isLength({ min: 2, max: 50 }),
  body('email').trim().isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }).matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // In a real app, hash the password before storing
  const { name, email } = req.body;

  // Create user logic here
  const newUser = {
    id: 3, // Would be generated by database
    name,
    email,
    role: 'user'
  };

  logger.info('New user created', { userId: newUser.id, email: newUser.email });
  res.status(201).json({
    message: 'User created successfully',
    user: {
      id: newUser.id,
      name: newUser.name,
      role: newUser.role
    }
  });
});

// 404 handler
app.use((req, res) => {
  logger.warn('404 Not Found', { url: req.url, method: req.method });
  res.status(404).json({ error: 'Not found' });
});

// Use environment variable for port
const port = process.env.PORT || 3000;
const server = app.listen(port, () => {
  logger.info(`Server running on port ${port} in ${process.env.NODE_ENV || 'development'} mode`);

  // Don't log sensitive information
  console.log(`Server started on port ${port}`);
});

// Graceful shutdown
const gracefulShutdown = () => {
  logger.info('Received shutdown signal');

  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    logger.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app;

