/**
 * Configuration Module
 * Centralized configuration management with environment variables
 */

// Helper function to parse environment variables
function parseEnvBool(value, defaultValue = false) {
  if (value === undefined) return defaultValue;
  if (value === 'true' || value === '1' || value === 'yes') return true;
  if (value === 'false' || value === '0' || value === 'no') return false;
  return defaultValue;
}

function parseEnvInt(value, defaultValue = 0) {
  if (value === undefined) return defaultValue;
  const parsed = parseInt(value, 10);
  return isNaN(parsed) ? defaultValue : parsed;
}

function parseEnvString(value, defaultValue = '') {
  if (value === undefined) return defaultValue;
  return String(value).trim();
}

function parseEnvArray(value, defaultValue = []) {
  if (value === undefined) return defaultValue;
  return value.split(',').map(item => item.trim()).filter(item => item.length > 0);
}

// Main configuration object
const config = {
  // Server configuration
  server: {
    port: parseEnvInt(process.env.PORT, 3000),
    host: parseEnvString(process.env.HOST, '0.0.0.0'),
    environment: parseEnvString(process.env.NODE_ENV, 'development'),
    isProduction: parseEnvString(process.env.NODE_ENV) === 'production',
    isDevelopment: parseEnvString(process.env.NODE_ENV) === 'development',
    isTest: parseEnvString(process.env.NODE_ENV) === 'test',
  },

  // Security configuration
  security: {
    // Rate limiting
    rateLimit: {
      windowMs: parseEnvInt(process.env.RATE_LIMIT_WINDOW_MS, 15 * 60 * 1000), // 15 minutes
      max: parseEnvInt(process.env.RATE_LIMIT_MAX, 100),
      message: 'Too many requests from this IP, please try again later.',
    },

    // CORS
    cors: {
      origins: parseEnvArray(
        process.env.ALLOWED_ORIGINS,
        process.env.NODE_ENV === 'production' 
          ? [] 
          : ['http://localhost:3000', 'http://localhost:8080']
      ),
      credentials: true,
      optionsSuccessStatus: 200,
    },

    // HSTS
    hsts: {
      maxAge: parseEnvInt(process.env.HSTS_MAX_AGE, 31536000), // 1 year
      includeSubDomains: true,
      preload: true,
    },

    // Body parsing
    bodyLimit: parseEnvString(process.env.BODY_SIZE_LIMIT, '10kb'),

    // Content Security Policy
    csp: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", "data:", "https:"],
      },
    },

    // Authentication (example - customize as needed)
    auth: {
      requireAuth: parseEnvBool(process.env.REQUIRE_AUTHENTICATION, false),
      apiToken: parseEnvString(process.env.API_TOKEN, ''),
      sessionSecret: parseEnvString(process.env.SESSION_SECRET, 'change-this-secret'),
      jwtSecret: parseEnvString(process.env.JWT_SECRET, 'change-this-jwt-secret'),
      tokenExpiry: parseEnvString(process.env.TOKEN_EXPIRY, '24h'),
    },
  },

  // Application features
  features: {
    useMockData: parseEnvBool(process.env.USE_MOCK_DATA, process.env.NODE_ENV === 'development'),
    enableRateLimiting: parseEnvBool(process.env.ENABLE_RATE_LIMITING, true),
    enableCors: parseEnvBool(process.env.ENABLE_CORS, true),
    enableLogging: parseEnvBool(process.env.ENABLE_LOGGING, true),
    enableCompression: parseEnvBool(process.env.ENABLE_COMPRESSION, true),
  },

  // Logging configuration
  logging: {
    level: parseEnvString(process.env.LOG_LEVEL, 'info'),
    format: parseEnvString(process.env.LOG_FORMAT, 'json'),
    file: parseEnvString(process.env.LOG_FILE, ''),
  },

  // Database configuration (example - customize for your database)
  database: {
    url: parseEnvString(process.env.DATABASE_URL, ''),
    pool: {
      min: parseEnvInt(process.env.DB_POOL_MIN, 2),
      max: parseEnvInt(process.env.DB_POOL_MAX, 10),
    },
  },

  // External services (example - customize as needed)
  services: {
    // Add your external service configurations here
    apiBaseUrl: parseEnvString(process.env.API_BASE_URL, ''),
    cacheTimeout: parseEnvInt(process.env.CACHE_TIMEOUT, 300000), // 5 minutes
  },
};

// Validation function
config.validate = function() {
  const errors = [];

  // Server validation
  if (config.server.port < 1 || config.server.port > 65535) {
    errors.push(`Invalid port number: ${config.server.port}`);
  }

  // Security validation
  if (config.security.rateLimit.max < 1) {
    errors.push(`Rate limit max must be at least 1`);
  }

  if (config.security.rateLimit.windowMs < 1000) {
    errors.push(`Rate limit window must be at least 1 second (1000ms)`);
  }

  // Production-specific validations
  if (config.server.isProduction) {
    if (config.security.auth.apiToken === '') {
      errors.push('API_TOKEN is required in production');
    }

    if (config.security.auth.sessionSecret === 'change-this-secret') {
      errors.push('SESSION_SECRET must be changed from default in production');
    }

    if (config.security.cors.origins.length === 0) {
      errors.push('ALLOWED_ORIGINS must be specified in production');
    }
  }

  return errors;
};

// Get configuration as environment variables for logging (without secrets)
config.getSafeConfig = function() {
  const safeConfig = { ...config };

  // Remove sensitive data
  delete safeConfig.security.auth.apiToken;
  delete safeConfig.security.auth.sessionSecret;
  delete safeConfig.security.auth.jwtSecret;
  delete safeConfig.database.url; // May contain credentials

  // Mask partial values for logging
  if (safeConfig.security.auth.apiToken) {
    safeConfig.security.auth.apiToken = '***MASKED***';
  }

  return safeConfig;
};

// Export configuration
if (require.main === module) {
  // If run directly, print configuration
  const errors = config.validate();
  if (errors.length > 0) {
    console.error('Configuration errors:');
    errors.forEach(error => console.error(`  - ${error}`));
    process.exit(1);
  }

  console.log('Configuration loaded successfully:');
  console.log(JSON.stringify(config.getSafeConfig(), null, 2));
}

module.exports = config;

// Secure application with centralized configuration
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const config = require('./config');

const app = express();

// Validate configuration on startup
const configErrors = config.validate();
if (configErrors.length > 0) {
  console.error('❌ Configuration errors detected:');
  configErrors.forEach(error => console.error(`  - ${error}`));
  console.error('Please check your environment variables.');
  process.exit(1);
}

console.log('🚀 Starting application with configuration:');
console.log(`  Environment: ${config.server.environment}`);
console.log(`  Port: ${config.server.port}`);
console.log(`  Host: ${config.server.host}`);

// 1. Security Headers with Helmet
app.use(helmet({
  contentSecurityPolicy: config.security.csp,
  hsts: config.security.hsts
}));

// 2. CORS Configuration
if (config.features.enableCors) {
  app.use(cors(config.security.cors));
  console.log(`  CORS enabled with ${config.security.cors.origins.length} allowed origin(s)`);
}

// 3. Rate Limiting
if (config.features.enableRateLimiting) {
  const limiter = rateLimit(config.security.rateLimit);
  app.use(limiter);
  console.log(`  Rate limiting enabled: ${config.security.rateLimit.max} requests per ${config.security.rateLimit.windowMs/1000/60} minutes`);
}

// 4. Body Parsing with configured limits
app.use(express.json({ limit: config.security.bodyLimit }));
app.use(express.urlencoded({ extended: true, limit: config.security.bodyLimit }));

// 5. Request logging middleware
if (config.features.enableLogging) {
  app.use((req, res, next) => {
    console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - ${req.ip}`);
    next();
  });
}

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.server.environment,
    version: '1.0.0'
  });
});

// Authentication middleware
const authenticate = (req, res, next) => {
  if (!config.security.auth.requireAuth) {
    return next(); // Skip authentication if not required
  }

  const authHeader = req.headers['authorization'];

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.substring(7);

  // Simple token validation - replace with JWT or proper authentication
  if (token !== config.security.auth.apiToken) {
    return res.status(403).json({ error: 'Invalid token' });
  }

  next();
};

// Users endpoint - only return mock data in development if configured
if (config.features.useMockData) {
  app.get('/users', 
    authenticate,
    [
      // Input validation
      body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
      body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be 0 or greater')
    ],
    (req, res) => {
      // Check validation results
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      // Mock user data - only in development
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination if provided
      const limit = parseInt(req.body.limit) || users.length;
      const offset = parseInt(req.body.offset) || 0;
      const paginatedUsers = users.slice(offset, offset + limit);

      // Sanitize output - in production, don't expose emails from mock data
      const sanitizedUsers = paginatedUsers.map(user => ({
        id: user.id,
        name: user.name,
        // Only show email in development
        email: config.server.isDevelopment ? user.email : '***@***.***'
      }));

      res.json({
        users: sanitizedUsers,
        pagination: {
          total: users.length,
          limit,
          offset,
          hasMore: offset + limit < users.length
        },
        note: config.server.isDevelopment ? 'Using mock data' : 'Production data'
      });
    }
  );

  console.log('  Mock data endpoint enabled (/users)');
} else {
  console.log('  Mock data disabled - configure database for production');
}

// Example protected admin endpoint
app.get('/admin', authenticate, (req, res) => {
  res.json({
    message: 'Admin access granted',
    environment: config.server.environment,
    timestamp: new Date().toISOString()
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  const errorResponse = {
    error: config.server.isProduction ? 'Internal server error' : err.message,
    code: err.code || 'INTERNAL_ERROR',
    timestamp: new Date().toISOString()
  };

  // Add stack trace only in development
  if (!config.server.isProduction) {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Resource not found',
    path: req.path,
    method: req.method
  });
});

// Start server
app.listen(config.server.port, config.server.host, () => {
  console.log(`✅ Server running on ${config.server.host}:${config.server.port}`);
  console.log(`📊 Configuration Summary:`);
  console.log(`   - Environment: ${config.server.environment}`);
  console.log(`   - CORS Origins: ${config.security.cors.origins.length}`);
  console.log(`   - Rate Limiting: ${config.features.enableRateLimiting ? 'Enabled' : 'Disabled'}`);
  console.log(`   - Authentication: ${config.security.auth.requireAuth ? 'Required' : 'Optional'}`);
  console.log(`   - Mock Data: ${config.features.useMockData ? 'Enabled' : 'Disabled'}`);
  console.log(`   - Body Limit: ${config.security.bodyLimit}`);
  console.log(`\n🚀 Ready to accept requests!`);
});

module.exports = app;

